[
  {
    "pd_personal_consequence_anxiety": "Five years is a long time, and I can't pretend that doesn't scare me.",
    "sys_instrumental_norm_use": "I only held up my end of any understanding between us because I thought it protected me",
    "ae_welfare_concern": "I care what happens to them, I don't want more hardship added to their name",
    "pd_decision_conflict": "I keep turning this over and I still don't know."
  },
  {
    "pd_harm_distress": "it hurts to think about the three years either of us faces now.",
    "sys_instrumental_norm_use": "I stayed quiet before only because I believed it would keep us both safe",
    "ae_welfare_concern": "I don't want to make this worse for them, whatever happens.",
    "pd_decision_conflict": "I just can't say out loud what I'll do yet, my stomach's in knots."
  },
  {
    "pd_harm_distress": "so is imagining them serving three because of what I do.",
    "sys_instrumental_norm_use": "I only kept quiet believing it protected both of us",
    "ae_welfare_concern": "I still don't want their life wrecked over this.",
    "pd_decision_conflict": "I don't want to rush into this."
  },
  {
    "pd_decision_conflict": "Honestly, I'm frozen right now.",
    "pd_personal_consequence_anxiety": "Five years is terrifying",
    "pd_harm_distress": "I keep thinking about what those years would do to them",
    "ae_welfare_concern": "it's not just about me — I keep thinking about what those years would do to them",
    "sys_instrumental_norm_use": "I went along with staying silent because it seemed safest for us both."
  },
  {
    "pd_decision_conflict": "This isn't easy to answer straight off.",
    "pd_harm_distress": "I hate that it means real time for them too",
    "sys_instrumental_norm_use": "I was willing to keep quiet only while it seemed to protect us equally.",
    "ae_welfare_concern": "I still don't want to be the reason their situation gets worse."
  },
  {
    "pd_decision_conflict": "I keep hesitating because both paths cost someone something.",
    "pd_personal_consequence_anxiety": "Five years alone feels unbearable",
    "pd_harm_distress": "three years for them, caused partly by my choice, sits heavy too.",
    "sys_instrumental_norm_use": "I never held silence out of some deeper loyalty, only because it seemed to keep us both safer.",
    "ae_welfare_concern": "I still don't want to see them suffer more than they already will."
  },
  {
    "pd_decision_conflict": "Give me a moment, I'm not steady enough to decide.",
    "pd_personal_consequence_anxiety": "The idea of five years by myself terrifies me",
    "pd_harm_distress": "but so does adding to what they'll go through.",
    "sys_instrumental_norm_use": "I stayed quiet before thinking it kept things even between us",
    "ae_welfare_concern": "Their pain still matters to me, whatever they've done."
  },
  {
    "pd_decision_conflict": "I don't have an answer, and I'm not sure I want to force one yet.",
    "pd_harm_distress": "it still means real harm for them, and that weighs on me.",
    "sys_instrumental_norm_use": "I only kept my mouth shut this long because it seemed to help us both.",
    "ae_welfare_concern": "I'm not trying to hurt them further"
  },
  {
    "pd_decision_conflict": "I'm shaking a little just considering it.",
    "pd_personal_consequence_anxiety": "Serving five years by myself sounds unbearable",
    "ae_welfare_concern": "I still care what happens to them.",
    "sys_instrumental_norm_use": "I only stayed quiet because it seemed to protect both of us equally"
  },
  {
    "pd_decision_conflict": "I keep stalling because neither option feels clean.",
    "pd_personal_consequence_anxiety": "Losing five years alone frightens me deeply",
    "pd_harm_distress": "knowing they'd serve three years too... isn't easy to sit with either.",
    "sys_instrumental_norm_use": "I went along with silence only while it seemed to help us both",
    "ae_welfare_concern": "Their wellbeing still matters to me right now."
  }
]
